function PipelineColumn({ title, icon, color, students, onOpen, emptyText, clickable, timestampKind }) {
  const [hoveredId, setHoveredId] = useState(null);
  return (
    <div style={{ flex: 1, minWidth: 240 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14 }}>
        <div style={{ width: 30, height: 30, borderRadius: 9, background: color, display: "flex", alignItems: "center", justifyContent: "center" }}>
          {icon}
        </div>
        <span style={{ fontWeight: 800, fontSize: 14.5, color: C.navy }}>{title}</span>
        <span style={{ fontSize: 12, fontWeight: 700, color: FAINT, marginLeft: "auto" }}>{students.length}</span>
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {students.length === 0 && (
          <div style={{ fontSize: 12.5, color: FAINT, fontStyle: "italic", padding: "10px 4px" }}>{emptyText}</div>
        )}
        {students.map((s) => {
          const hovered = hoveredId === s.id;
          return (
            <div
              key={s.id}
              onClick={() => clickable && onOpen(s.id)}
              onMouseEnter={() => setHoveredId(s.id)}
              onMouseLeave={() => setHoveredId(null)}
              className="qq-card"
              style={{
                padding: "14px 16px", cursor: clickable ? "pointer" : "default",
                border: `1px solid ${BORDER}`,
                boxShadow: hovered && clickable ? "0 14px 28px -14px rgba(0,52,104,0.35)" : "0 6px 16px -12px rgba(0,52,104,0.2)",
                transform: hovered && clickable ? "translateY(-2px)" : "none",
                transition: "transform 0.15s ease, box-shadow 0.15s ease",
                display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8,
              }}
            >
              <div>
                <div style={{ fontWeight: 700, fontSize: 13.5, color: C.ink }}>{s.name}</div>
                <div style={{ fontSize: 11.5, color: FAINT }}>{s.grade}</div>
                {timestampKind && (
                  <div style={{ fontSize: 11, color: MUTED, marginTop: 3 }}>{seededTimeAgo(s.name, timestampKind)}</div>
                )}
              </div>
              {clickable && (
                <ChevronRight
                  size={16}
                  color={C.blue}
                  style={{ opacity: hovered ? 1 : 0, transition: "opacity 0.15s ease", flexShrink: 0 }}
                />
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function PipelineScreen({ go, students, openReview }) {
  const notStarted = students.filter((s) => s.status === "not_started");
  const submitted = students.filter((s) => s.status === "submitted");
  const sent = students.filter((s) => s.status === "sent");

  return (
    <div style={{ minHeight: "100vh", background: C.cream }} className="qq-fade-in">
      <HeroSection height="auto">
        <AppHeader isAdmin name="Admin" email="admin@edjuvenate.com" onLogout={() => go("adminLogin")} />
        <div style={{ padding: "6px 40px 44px" }}>
          <div className="qq-heading" style={{ fontSize: 30, color: C.white, marginBottom: 6 }}>Submissions pipeline</div>
          <p style={{ color: "rgba(255,255,255,0.7)", fontSize: 14 }}>Track every student from quest to sent report.</p>
        </div>
      </HeroSection>
      <Wave fill={C.cream} height={48} />

      <div style={{ maxWidth: 980, margin: "0 auto", padding: "20px 24px 0" }}>
        <AdminTabBar current="pipeline" go={go} />
      </div>

      <div style={{ maxWidth: 980, margin: "-20px auto 0", padding: "0 24px 80px" }}>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 16, marginBottom: 28 }} className="qq-report-grid">
          {[
            { label: "Not started", value: notStarted.length, color: SURFACE_2 },
            { label: "Awaiting review", value: submitted.length, color: SKY_TINT },
            { label: "Sent to parents", value: sent.length, color: SKY_TINT_STRONG },
          ].map((s) => (
            <div key={s.label} className="qq-card" style={{ padding: "20px 18px" }}>
              <div style={{ fontSize: 24, fontWeight: 800, color: C.navy }}>{s.value}</div>
              <div style={{ fontSize: 12, fontWeight: 700, color: LABELG }}>{s.label}</div>
            </div>
          ))}
        </div>

        <Card>
          <div style={{ display: "flex", gap: 28, flexWrap: "wrap" }}>
            <PipelineColumn
              title="Not started" color={SURFACE_2} icon={<CircleDashed size={16} color={MUTED} />}
              students={notStarted} onOpen={openReview} emptyText="Everyone has started their quest."
              clickable={false}
            />
            <PipelineColumn
              title="Awaiting review" color={SKY_TINT} icon={<CircleEllipsis size={16} color={C.blue} />}
              students={submitted} onOpen={openReview} emptyText="Nothing waiting on review."
              clickable timestampKind="submitted"
            />
            <PipelineColumn
              title="Sent to parents" color={SKY_TINT_STRONG} icon={<CircleCheck size={16} color={C.blue} />}
              students={sent} onOpen={openReview} emptyText="No reports sent yet."
              clickable timestampKind="sent"
            />
          </div>
        </Card>
        <div style={{ marginTop: 20 }}>
          <MockNote>pipeline status updates in real time from submission + email-send webhooks here.</MockNote>
        </div>
      </div>
    </div>
  );
}

/* =========================================================================
   ROOT APP
   ========================================================================= */

export default function App() {
  const [screen, setScreen] = useState("login");
  const [studentName, setStudentName] = useState("tanvi");

  const [currentQ, setCurrentQ] = useState(0);
  const [answers, setAnswers] = useState({});
  const [timeLeft, setTimeLeft] = useState(45 * 60);

  const [students, setStudents] = useState(INITIAL_STUDENTS);
  const [selected, setSelected] = useState([]);
  const [reviewStudentId, setReviewStudentId] = useState(null);

  // The logged-in student's own record in the shared roster — this is the
  // single source of truth for "is my report ready yet" (requirement: a
  // student's report must not be visible until an admin has approved it).
  const myStudent = students.find((s) => sameFirstName(s.name, studentName)) || null;

  function go(nextScreen, opts = {}) {
    if (opts.studentName) setStudentName(opts.studentName);
    if (nextScreen === "assessment" && screen !== "assessment") {
      setCurrentQ(0); setAnswers({}); setTimeLeft(45 * 60);
    }
    window.scrollTo({ top: 0, behavior: "instant" in window ? "instant" : "auto" });
    setScreen(nextScreen);
  }

  // Called from the assessment's "Submit Quest" button. Creates or updates
  // this student's roster record with status "submitted" (awaiting admin
  // review) — their report only becomes visible once an admin approves it.
  function submitAssessment() {
    const normalized = normalizeAnswers(answers);
    const name = studentName || "you";
    const scores = seededScores(name);
    const letter = generateLetter(name, scores);
    setStudents((prev) => {
      const idx = prev.findIndex((s) => sameFirstName(s.name, name));
      if (idx === -1) {
        const nextId = prev.length ? Math.max(...prev.map((s) => s.id)) + 1 : 1;
        return [...prev, {
          id: nextId, name, email: `${name.toLowerCase().replace(/\s+/g, "")}@edjuvenate.com`,
          grade: "Grade 6", status: "submitted", scores, letter, answers: normalized,
        }];
      }
      const copy = [...prev];
      copy[idx] = { ...copy[idx], status: "submitted", scores, letter, answers: normalized };
      return copy;
    });
    go("submission");
  }

  const [scrollToLetter, setScrollToLetter] = useState(false);

  function openReview(id, opts = {}) {
    setReviewStudentId(id);
    setScrollToLetter(!!opts.scrollToLetter);
    setScreen("reportReview");
  }

  function handleApprove(id) {
    setStudents((prev) => prev.map((s) => (s.id === id ? { ...s, status: "sent" } : s)));
  }

  function handleRegenerate(id) {
    setStudents((prev) => prev.map((s) => {
      if (s.id !== id) return s;
      const nudged = s.scores.map((sc) => ({ ...sc, score: Math.max(40, Math.min(99, sc.score + (Math.round(Math.random() * 14) - 7))) }));
      return { ...s, scores: nudged, letter: generateLetter(s.name.split(" ")[0], nudged) };
    }));
  }

  function resetDemo() {
    setScreen("login");
    setStudentName("tanvi");
    setCurrentQ(0); setAnswers({}); setTimeLeft(45 * 60);
    setStudents(INITIAL_STUDENTS);
    setSelected([]);
    setReviewStudentId(null);
  }

  const reviewStudent = students.find((s) => s.id === reviewStudentId) || null;

  let ScreenView;
  switch (screen) {
    case "signup": ScreenView = <SignupScreen go={go} />; break;
    case "login": ScreenView = <LoginScreen go={go} />; break;
    case "dashboard": ScreenView = <StudentDashboard go={go} studentName={studentName} myStudent={myStudent} />; break;
    case "assessmentIntro": ScreenView = <AssessmentIntroScreen go={go} />; break;
    case "assessment": ScreenView = (
      <AssessmentScreen
        go={go}
        submitAssessment={submitAssessment}
        currentQ={currentQ} setCurrentQ={setCurrentQ}
        answers={answers} setAnswers={setAnswers}
        timeLeft={timeLeft} setTimeLeft={setTimeLeft}
      />
    ); break;
    case "submission": ScreenView = <SubmissionScreen go={go} />; break;
    case "studentReport": ScreenView = <StudentReportScreen go={go} studentName={studentName} myStudent={myStudent} />; break;
    case "adminLogin": ScreenView = <AdminLoginScreen go={go} />; break;
    case "adminDashboard": ScreenView = <AdminDashboard go={go} students={students} selected={selected} setSelected={setSelected} openReview={openReview} />; break;
    case "reportReview": ScreenView = <ReportReviewScreen go={go} student={reviewStudent} onApprove={handleApprove} onRegenerate={handleRegenerate} scrollToLetter={scrollToLetter} />; break;    case "pipeline": ScreenView = <PipelineScreen go={go} students={students} openReview={openReview} />; break;
    default: ScreenView = <LoginScreen go={go} />;
  }

  return (
    <div className="qq-root">
      <GlobalStyle />
      {ScreenView}
      <DevNav current={screen} onNavigate={go} onReset={resetDemo} />
    </div>
  );
}